<script setup lang="ts">
import {computed,watch,onMounted,onBeforeUnmount,ref,nextTick} from 'vue'
import Icon from './Icon.vue'
import {state,t,fmt,api,wp,notify} from '../state'
const e=computed(()=>state.selectedEvent)
const c=computed(()=>e.value?.[state.locale]||e.value?.en)
const tab=ref('analysis'),question=ref(''),answer=ref<any>(null),busy=ref(false),drawer=ref<HTMLElement>()
const previous=ref<any>()
watch(e,async(v)=>{if(v){previous.value=document.activeElement;tab.value='analysis';answer.value=null;await nextTick();drawer.value?.focus();document.body.style.overflow='hidden'}else{document.body.style.overflow='';previous.value?.focus?.()}})
function close(){state.selectedEvent=null}
function key(ev:KeyboardEvent){if(ev.key==='Escape')close();if(ev.key==='Tab'&&e.value){const nodes=drawer.value?.querySelectorAll<HTMLElement>('button,a[href],input,textarea,select,[tabindex="0"]');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus()}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus()}}}
onMounted(()=>document.addEventListener('keydown',key));onBeforeUnmount(()=>document.removeEventListener('keydown',key))
async function feedback(rating:string){try{await api(wp('/events/'+e.value.id+'/feedback'),{method:'POST',body:{rating}});notify(t('Thank you. Your feedback helps improve relevance.','Спасибо. Ваш отзыв поможет улучшить релевантность.'))}catch(err:any){notify(err.message,true)}}
async function save(){const saved=!state.saved.includes(e.value.id);try{await api(wp('/events/'+e.value.id+'/save'),{method:'POST',body:{saved}});state.saved=saved?[...state.saved,e.value.id]:state.saved.filter(x=>x!==e.value.id);notify(saved?t('Saved to your reading list','Добавлено в избранное'):t('Removed from saved','Удалено из избранного'))}catch(err:any){notify(err.message,true)}}
async function ask(){if(!question.value.trim())return;busy.value=true;try{answer.value=await api(wp('/assistant'),{method:'POST',body:{question:question.value,event_id:e.value.id,locale:state.locale}})}catch(err:any){notify(err.message,true)}finally{busy.value=false}}
</script>
<template><Teleport to="body"><div v-if="e" class="drawer-backdrop" @click.self="close"><section class="event-drawer" role="dialog" aria-modal="true" aria-labelledby="event-title" tabindex="-1" ref="drawer">
  <div class="drawer-top"><span class="eyebrow">{{t('BUSINESS SIGNAL','БИЗНЕС-СИГНАЛ')}}</span><div class="row"><button class="icon-btn" @click="save" :aria-label="t('Save event','Сохранить событие')"><Icon :name="state.saved.includes(e.id)?'BookmarkCheck':'Bookmark'"/></button><button class="icon-btn" @click="close" :aria-label="t('Close event','Закрыть событие')"><Icon name="X"/></button></div></div>
  <div class="row gap-sm wrap"><span class="badge" :class="e.sentiment">{{t({risk:'Risk',opportunity:'Opportunity',mixed:'Mixed impact',neutral:'Neutral'}[e.sentiment],{risk:'Риск',opportunity:'Возможность',mixed:'Смешанное влияние',neutral:'Нейтрально'}[e.sentiment])}}</span><span class="muted small">{{fmt(e.published_at,{dateStyle:'medium'})}}</span><span v-if="e.is_demo" class="badge neutral">{{t('Synthetic scenario','Учебный сценарий')}}</span></div>
  <h1 id="event-title">{{c.title}}</h1>
  <div class="drawer-scores"><div><strong>{{e.relevance}}<small>%</small></strong><span>{{t('Business relevance','Значимость для бизнеса')}}</span></div><div><strong>{{e.confidence}}<small>%</small></strong><span>{{t('Evidence confidence','Уверенность в выводе')}}</span></div><div><strong><Icon name="Clock3" :size="25"/></strong><span>{{t({days:'Days',weeks:'Weeks',months:'Months'}[e.time_horizon]||'Weeks',{days:'Дни',weeks:'Недели',months:'Месяцы'}[e.time_horizon]||'Недели')}}</span></div></div>
  <div class="tabs"><button :class="{active:tab==='analysis'}" @click="tab='analysis'">{{t('Impact analysis','Влияние на бизнес')}}</button><button :class="{active:tab==='evidence'}" @click="tab='evidence'">{{t('Sources & reasoning','Источники и основания')}}</button></div>
  <template v-if="tab==='analysis'"><div class="analysis-section"><span class="section-kicker"><Icon name="Newspaper" :size="15"/>{{t('REPORTED FACT','ФАКТ ИЗ ИСТОЧНИКА')}}</span><p>{{c.fact}}</p></div><div class="analysis-section why-box"><span class="section-kicker"><Icon name="Building2" :size="15"/>{{t('WHY IT MATTERS TO YOU','ПОЧЕМУ ЭТО ВАЖНО ДЛЯ ВАС')}}</span><p>{{c.why}}</p><div class="chips"><span v-for="f in e.profile_features" :key="f" class="chip">{{t({exposures:'Business exposures',priorities:'Priorities',industry:'Industry',regions:'Geography',counterparties:'Counterparties',activities:'Activities'}[f]||f,{exposures:'Факторы влияния',priorities:'Приоритеты',industry:'Отрасль',regions:'Регионы',counterparties:'Контрагенты',activities:'Деятельность'}[f]||f)}}</span></div></div><div class="analysis-section"><span class="section-kicker"><Icon name="GitBranch" :size="15"/>{{t('POTENTIAL BUSINESS IMPACT','ВОЗМОЖНОЕ ВЛИЯНИЕ НА БИЗНЕС')}}</span><p>{{c.impact}}</p><span class="small muted">{{t('AI interpretation · conditional scenario','Интерпретация ИИ · условный сценарий')}}</span></div><div class="bank-box"><span class="bank-mark">A</span><div><h4>{{t('Alfa-Bank perspective','Взгляд Альфа-Банка')}}</h4><p>{{c.bank_view}}</p><span v-if="e.bank_evidence?.length" class="small muted">{{t('Based on research dated','На основе обзора от')}} {{fmt(e.bank_evidence[0].published_at)}} · {{t('Historical context','Исторический контекст')}}</span></div></div><div class="analysis-section"><span class="section-kicker"><Icon name="ListChecks" :size="15"/>{{t('A USEFUL NEXT MOVE','СЛЕДУЮЩИЙ ШАГ')}}</span><div v-for="a in c.actions" :key="a" class="action-item"><Icon name="ArrowRight" :size="17"/><p>{{a}}</p></div></div><div class="uncertainty"><Icon name="Info" :size="17"/><div><h4>{{t('What still needs checking','Что ещё нужно уточнить')}}</h4><p v-for="u in c.uncertainties" :key="u">{{u}}</p></div></div></template>
  <template v-else><div class="analysis-section"><h3>{{t('Original reporting','Первичный источник')}}</h3><p>{{e.article?.title}}</p><a v-if="e.article?.url" :href="e.article.url" target="_blank" rel="noopener noreferrer" class="text-link">{{e.article.source_name}} <Icon name="ExternalLink" :size="14"/></a><div v-else class="notice">{{t('This is a synthetic demonstration event, not a real news report.','Это учебное событие, а не реальная новость.')}}</div><pre class="evidence-text">{{e.article?.text}}</pre><span class="small muted">{{t('Evidence level','Тип доказательства')}}: {{e.article?.evidence_level}}</span></div><div v-for="b in e.bank_evidence" :key="b.id" class="research-card"><span class="bank-tag">{{t('BANK RESEARCH','АНАЛИТИКА БАНКА')}}</span><h4>{{b.title}}</h4><p class="small muted">{{fmt(b.published_at)}} · {{t('Page','Страница')}} {{b.page}} <span v-if="b.ocr">· OCR</span></p><blockquote>{{e.bank_quote||b.text}}</blockquote><a :href="b.url" target="_blank" rel="noopener noreferrer" class="text-link">{{t('Open original research','Открыть оригинал')}}<Icon name="ExternalLink" :size="14"/></a></div><div v-if="!e.bank_evidence?.length" class="empty compact-empty"><Icon name="BookOpen"/><p>{{t('No directly supporting bank excerpt was verified for this event.','Для события не подтверждена прямая цитата из аналитики банка.')}}</p></div><div class="analysis-section"><h3>{{t('Analysis provenance','Происхождение анализа')}}</h3><dl class="detail-list"><dt>{{t('Company profile version','Версия профиля')}}</dt><dd>{{e.profile_version}}</dd><dt>{{t('Analysed for','Роль пользователя')}}</dt><dd>{{e.decision_role.toUpperCase()}}</dd><dt>{{t('Prepared','Подготовлено')}}</dt><dd>{{fmt(e.generated_at,{dateStyle:'medium',timeStyle:'short'})}}</dd></dl><RouterLink class="text-link" to="/sources?tab=runs" @click="close">{{t('Inspect the agent run','Посмотреть шаги агента')}}<Icon name="ArrowRight" :size="15"/></RouterLink></div></template>
  <div class="drawer-question"><h3>{{t('Go one question deeper','Разобраться глубже')}}</h3><form @submit.prevent="ask"><label class="sr-only" for="event-question">{{t('Ask about this event','Вопрос о событии')}}</label><input id="event-question" v-model="question" :placeholder="t('What should our finance team check first?','Что стоит проверить финансовому отделу?')" maxlength="1500"><button class="btn primary" :disabled="busy||!question.trim()"><Icon :name="busy?'LoaderCircle':'ArrowUp'" :class="{spin:busy}" :size="17"/></button></form><p v-if="answer" class="answer-text">{{answer.answer}}</p></div>
  <div class="feedback-row"><span>{{t('Was this useful?','Это было полезно?')}}</span><button class="btn ghost small-btn" @click="feedback('useful')"><Icon name="ThumbsUp" :size="15"/>{{t('Useful','Полезно')}}</button><button class="btn ghost small-btn" @click="feedback('irrelevant')"><Icon name="ThumbsDown" :size="15"/>{{t('Not relevant','Не по теме')}}</button><button class="icon-btn" @click="feedback('incorrect')" :aria-label="t('Report incorrect analysis','Сообщить об ошибке')"><Icon name="Flag" :size="15"/></button></div>
</section></div></Teleport></template>
